{
	"name": "@mburghardt/opencode-metrics",
	"version": "0.6.0",
	"description": "OpenCode plugin for automatic session metrics collection and analytics",
	"license": "Apache-2.0",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/marcusburghardt/opencode-metrics.git"
	},
	"type": "module",
	"files": [
		"dist/"
	],
	"main": "dist/index.js",
	"exports": {
		".": "./dist/index.js"
	},
	"scripts": {
		"build": "bun build src/index.ts --outdir dist --target bun --external @opencode/plugin",
		"test": "bun test --coverage",
		"lint": "bunx biome check ."
	},
	"keywords": [
		"opencode",
		"metrics",
		"plugin",
		"analytics"
	],
	"devDependencies": {
		"@biomejs/biome": "^2.5.13"
	},
	"dependencies": {
		"yaml": "^2.9.1",
		"@opencode/plugin": "2.2.5"
	}
}
